Reuse existing sliding-window implementation from `rateLimit.ts`. Key by IP address (requires `trustProxy: true` in Fastify config, already set).

Pseudo-code:
```ts
// In backend/src/routes/match.ts
import { RateLimiter } from '../lib/rateLimit.js'

const matchLimiter = new RateLimiter(
  config.MATCH_RATE_MAX_PER_IP,
  config.MATCH_RATE_WINDOW_MINUTES * 60 * 1000
)

app.post('/api/protests/match', async (req, reply) => {
  const ip = req.ip
  if (!matchLimiter.check(ip)) {
    return reply.code(429).header('Retry-After', '600').send({
      error: 'rate_limit_exceeded',
      message: 'Too many route requests. Try again later.'
    })
  }

  // existing match logic...
})
```

