// Backend
export async function organizationRoutes(app: FastifyInstance) {
  app.get('/api/organizations', async () => {
    const res = await query('select * from organizations order by name')
    return { organizations: res.rows }
  })

  app.post('/api/organizations', { onRequest: [app.requireRole('approved')] }, async (req, reply) => {
    const { name, description, website, social_links } = validateOrgInput(req.body)
    const res = await query(
      'insert into organizations (name, description, website, social_links) values ($1, $2, $3, $4) returning *',
      [name, description, website, social_links]
    )
    return reply.code(201).send(res.rows[0])
  })
}
```

Standardize error/loading/empty state patterns across all frontend components:

1. **Loading states:** Show spinner during API calls (use consistent LoadingSpinner component)
2. **Error states:** Display user-friendly error messages for common errors (network failure, 401/403, 429 rate limit, 503 routing unconfigured). Include retry button.
3. **Empty states:** Show helpful messages when no data (e.g., "No protests found", "No chips nearby")
4. **Form validation:** Real-time validation with clear inline error messages
5. **Toast notifications:** Success/error toasts for actions (chip dropped, protest created)

Create reusable components:
- `LoadingSpinner.tsx` - animated spinner with optional message
- `ErrorMessage.tsx` - error display with retry button
- `EmptyState.tsx` - illustration + message for empty data
- `Toast.tsx` - notification system (success/error/info)

Handle specific backend errors:
- 503 routing_unconfigured -> "Route planning unavailable. Admin needs to configure routing service."
- 429 rate_limit_exceeded -> "Too many requests. Please wait X minutes."
- 401/403 -> Redirect to login
- Network error -> "Network error. Check your connection and try again."

Pseudo-code:
```tsx
const MatchPanel = () => {
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string>()
  const [result, setResult] = useState<MatchResponse>()

  const handlePlanRoute = async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await api.matchRoute({ origin, destination })
      setResult(res)
    } catch (err) {
      if (err.status === 503 && err.error === 'routing_unconfigured') {
        setError('Route planning unavailable. Please try again later.')
      } else if (err.status === 429) {
        setError('Too many requests. Please wait and try again.')
      } else {
        setError('An error occurred. Please try again.')
      }
    } finally {
      setLoading(false)
    }
  }

  if (loading) return <LoadingSpinner message="Planning route..." />
  if (error) return <ErrorMessage message={error} onRetry={handlePlanRoute} />
  if (!result) return <EmptyState message="Enter destination to plan route" />

  return <MatchResult result={result} />
}
```

